+                            .switchIfEmpty(Mono.error(() -> new UnsatisfiedAttributeValueException(
+                                    "problemDetail.user.signup.defaultRoleMissing")))
+                            .flatMap(defaultRole -> userService.createUser(newUser, Set.of(defaultRole)));
